12	typealias PinnedEventsTimelineScreenViewModelType = StateStoreViewModel<PinnedEventsTimelineScreenViewState, PinnedEventsTimelineScreenViewAction>
13	
14	class PinnedEventsTimelineScreenViewModel: PinnedEventsTimelineScreenViewModelType, PinnedEventsTimelineScreenViewModelProtocol {
15	    private let roomProxy: JoinedRoomProxyProtocol
16	    private let userIndicatorController: UserIndicatorControllerProtocol
17	    private let appSettings: AppSettings
18	    private let analyticsService: AnalyticsService
19	    
20	    private let actionsSubject: PassthroughSubject<PinnedEventsTimelineScreenViewModelAction, Never> = .init()
21	    var actionsPublisher: AnyPublisher<PinnedEventsTimelineScreenViewModelAction, Never> {
22	        actionsSubject.eraseToAnyPublisher()
23	    }
24	    
25	    init(roomProxy: JoinedRoomProxyProtocol,
26	         userIndicatorController: UserIndicatorControllerProtocol,
27	         appSettings: AppSettings,
28	         analyticsService: AnalyticsService) {
29	        self.roomProxy = roomProxy
30	        self.userIndicatorController = userIndicatorController
31	        self.appSettings = appSettings
32	        self.analyticsService = analyticsService
33	        super.init(initialViewState: PinnedEventsTimelineScreenViewState())
34	    }
35	    
36	    // MARK: - Public
37	    
38	    override func process(viewAction: PinnedEventsTimelineScreenViewAction) {
39	        MXLog.info("View model: received view action: \(viewAction)")
40	        
41	        switch viewAction {
42	        case .close:
43	            analyticsService.trackInteraction(name: .PinnedMessageBannerCloseListButton)
44	            actionsSubject.send(.dismiss)
45	        }
46	    }
47	    
48	    func stop() {
49	        // Work around QLPreviewController dismissal issues, see the InteractiveQuickLookModifier.
50	        state.bindings.mediaPreviewViewModel = nil
51	    }
52	    
53	    func displayMediaPreview(_ mediaPreviewViewModel: TimelineMediaPreviewViewModel) {
54	        mediaPreviewViewModel.actions.sink { [weak self] action in
55	            guard let self else { return }
56	            switch action {
57	            case .displayMessageForwarding(let forwardingItem):
58	                state.bindings.mediaPreviewViewModel = nil
59	                // We need a small delay because we need to wait for the media preview to be fully dismissed.
60	                DispatchQueue.main.asyncAfter(deadline: .now() + TimelineMediaPreviewViewModel.displayMessageForwardingDelay) {
61	                    self.actionsSubject.send(.displayMessageForwarding(forwardingItem))
62	                }
63	            case .viewInRoomTimeline(let itemID):
64	                guard let eventID = itemID.eventID else {
65	                    return
66	                }
67	                Task { await self.viewInRoomTimeline(eventID: eventID) }
68	            case .dismiss:
69	                state.bindings.mediaPreviewViewModel = nil
70	            }
71	        }
72	        .store(in: &cancellables)
73	        
74	        state.bindings.mediaPreviewViewModel = mediaPreviewViewModel
75	    }
76	    
77	    private func viewInRoomTimeline(eventID: String) async {
78	        switch await roomProxy.loadOrFetchEventDetails(for: eventID) {
79	        case .success(let event):
80	            let threadRootEventID: String? = if appSettings.threadsEnabled {
81	                event.threadRootEventId()
82	            } else {
83	                nil
84	            }
85	            actionsSubject.send(.viewInRoomTimeline(eventID: eventID, threadRootEventID: threadRootEventID))
86	        case .failure:
87	            userIndicatorController.submitIndicator(.init(title: L10n.errorUnknown))
88	        }
89	    }
90	}
